	private bool showBattleActionTagsEffectsAfterOmenDataTagsEffects;

	[Header("Compendium Item State")]
	[SerializeField]
	private CompendiumItemState compendiumItemState;

	[Header("Difficulty Level Omen Data")]
	[SerializeField]
	private bool difficultyLevelOmenData;

