	public CompendiumItemState CompendiumItemState => compendiumItemState;

	public bool DifficultyLevelOmenData => difficultyLevelOmenData;

	public int Counter => counter;

	protected LocalizationManager localizationManager => ReferenceSingleton<LocalizationManager>.Instance;

	public string GetChapterAppearanceText()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetChapterAppearanceText(ChapterMute);
	}

	public virtual void Initialize(OmenInstance omenInstance)
	{
	}

	public virtual void OmenRemoved()
	{
	}

	public virtual string OmenConvertedDescription()
	{
		switch (omenDescriptionType)
		{
		case OmenDescriptionType.Direct:
		{
			string text4 = GetOmenRawLocalizedDescription();
			if (EnableActionValue)
			{
				text4 = Smart.Format(text4, ActionValue);
			}
			else if (EnableOmenCounter)
			{
				text4 = Smart.Format(text4, TriggerAmount);
			}
			return CheckAppendCounterKeptBetweenBattlesDescription(text4);
		}
		case OmenDescriptionType.DirectBattleAction:
		{
			string text2 = GetOmenRawLocalizedDescription();
			if (EnableOmenCounter)
			{
				text2 = Smart.Format(text2, TriggerAmount);
			}
			BattleAction.GetActionDescription(ActionValue);
			string text3 = BattleAction.GetActionDescription(ActionValue);
			if (!ignoreLowerCaseFirstLetterBattleAction)
			{
				text3 = text3.LowercaseFirst();
			}
			text2 = text2 + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + text3;
			return CheckAppendCounterKeptBetweenBattlesDescription(text2);
		}
		case OmenDescriptionType.DirectLogic:
		{
			string description = Smart.Format(GetOmenRawLocalizedDescription(), GetLocalizedOmenLogicDescription());
			return CheckAppendCounterKeptBetweenBattlesDescription(description);
		}
		case OmenDescriptionType.LogicBattleAction:
		{
			string localizedOmenLogicDescription = GetLocalizedOmenLogicDescription();
			return CheckAppendCounterKeptBetweenBattlesDescription(localizedOmenLogicDescription);
		}
		case OmenDescriptionType.BattleAction:
		{
			string text = GetOmenConvertedDescriptionBattleAction();
			if (text.Substring(0, 3) != "ALL" && !ignoreLowerCaseFirstLetterBattleAction)
			{
				text = text.LowercaseFirst();
			}
			return CheckAppendCounterKeptBetweenBattlesDescription(text);
		}
		default:
			return "";
		}
	}

	protected virtual string GetOmenRawLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(omenIDDescription);
	}

	public string GetOmenConvertedDescriptionBattleAction()
	{
		return BattleAction.GetActionDescription(ActionValue);
	}

	protected string GetLocalizedOmenLogicDescription()
	{
		return OmenLogic.GetLocalizedOmenLogicDescription(BattleAction, ActionValue);
	}

	protected string CheckAppendCounterKeptBetweenBattlesDescription(string description)
	{
		if (KeepOmenCounterBetweenBattles)
		{
			return description + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CounterKeptBetweenBattles");
		}
		return description;
	}

	public string GetOmenName()
	{
		if (getDirectOmenIDOnName)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(omenID);
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(omenIDName);
	}

	public virtual void ActivateOmen(GameObject target = null)
	{
		ActivateOmen(ActionValue, target);
	}

	public virtual void ActivateOmen(int actionAmount, GameObject target = null)
	{
		if (AlreadyUsed)
		{
			return;
		}
		if (EnableOmenCounter)
		{
			counter++;
			if (counter >= TriggerAmount)
			{
				counter = 0;
				if (EnableOmenLogic)
				{
					OmenLogicActiveOmen(actionAmount, target);
					return;
				}
				Debug.LogFormat("No Omen Logic: {0}", base.name);
			}
		}
		else if (EnableOmenLogic)
		{
			OmenLogicActiveOmen(actionAmount, target);
		}
		else
		{
			Debug.LogFormat("No Omen Logic: {0}", base.name);
		}
	}

	protected virtual void OmenLogicActiveOmen(int actionAmount, GameObject target = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		OmenLogic.ActivateOmen(BattleAction, actionAmount, target, null, corruptionPurifyModifierEnum);
	}

	protected void ActivateOmenWithoutCounter(GameObject target = null)
	{
		ActivateOmenWithoutCounter(ActionValue, target);
	}

	protected void ActivateOmenWithoutCounter(int actionAmount, GameObject target = null)
	{
		if (EnableOmenLogic)
		{
			OmenLogic.ActivateOmen(BattleAction, actionAmount, target, null);
			return;
		}
		Debug.LogFormat("No Omen Logic: {0}", base.name);
	}

	public void SetCounter(int counter)
	{
		this.counter = counter;
	}

	public void RestartCounter()
	{
		counter = 0;
	}

	public void ToggleAlreadyUsed(bool toggle)
	{
		AlreadyUsed = toggle;
	}

	public void SetCompendiumItemState(CompendiumItemState compendiumItemState)
	{
		this.compendiumItemState = compendiumItemState;
	}

	public virtual void InitializeActionDescriptionPanel()
	{
	}
}
